begin; do $$ declare actor uuid; rid uuid:=gen_random_uuid(); op uuid:=gen_random_uuid(); saved jsonb; reopened jsonb; repeat_result jsonb; changed jsonb; marker jsonb:='{"test":"synthetic-reopen-no-patient"}'::jsonb; begin select auth_user_id into actor from public.gerontik_learning_profiles where email='andazmortin@gmail.com' and 'super_admin'=any(roles); if actor is null then raise exception 'TEST_ACTOR_MISSING';end if; insert into public.gerontik_learning_roster(id,period,name,auth_user_id,program,group_name) values(rid,'_audit_reopen_20261112','Synthetic rollback test',actor,'TEST','TEST'); saved:=public.gerontik_learning_save(actor,'_audit_reopen_20261112',marker,0,gen_random_uuid(),true); if saved->>'documentStatus'<>'FINAL' then raise exception 'FINAL_NOT_SAVED';end if; begin perform public.gerontik_learning_reopen(gen_random_uuid(),rid,1,gen_random_uuid(),'Unauthorized test'); raise exception 'AUTHORIZATION_NOT_ENFORCED'; exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end; reopened:=public.gerontik_learning_reopen(actor,rid,1,op,'Synthetic correction'); if reopened->>'documentStatus'<>'DRAFT' or (reopened->>'revision')::integer<>2 then raise exception 'REOPEN_WRONG_RESULT';end if; repeat_result:=public.gerontik_learning_reopen(actor,rid,1,op,'Synthetic correction'); if repeat_result<>reopened then raise exception 'RETRY_NOT_IDEMPOTENT';end if; changed:=public.gerontik_learning_reopen(actor,rid,1,op,'Changed reason'); if changed->>'status'<>'idempotency_conflict' then raise exception 'MUTATED_RETRY_ACCEPTED';end if; if (select state from public.gerontik_learning_documents where owner_id=actor and period='_audit_reopen_20261112')<>marker then raise exception 'STATE_CHANGED';end if; if (select count(*) from public.gerontik_learning_document_versions where owner_id=actor and period='_audit_reopen_20261112')<>2 then raise exception 'SNAPSHOT_LOST';end if; changed:=public.gerontik_learning_save(actor,'_audit_reopen_20261112',marker,1,gen_random_uuid(),false); if changed->>'status'<>'conflict' then raise exception 'STALE_WRITE_ACCEPTED';end if; end $$; rollback; select 'passed: permission, revision, idempotency, immutable state, snapshot retention and stale save; all test writes rolled back' as verification;